const apiUrl = (global.get("neurolinkApiUrl") || "http://127.0.0.1:4000").replace(/\/+$/, "");
const secret = global.get("ingestSecret") || "neurolink-nodered-dev-secret";
const defaultCode = global.get("defaultDeviceCode") || "NL-HOLTER-01";
const headers = {
    "x-nodered-secret": secret,
    "Content-Type": "application/json"
};

const raw = msg.payload;
const buf = Buffer.isBuffer(raw) ? raw : null;

// 1) Binary 197-byte ESP32-ADS1299 frame: 0xA5 0xC2 0x11 0xD3 [48 float32 LE = 6x8ch uV] 0x5A
if (
    buf &&
    buf.length >= 197 &&
    buf[0] === 0xA5 &&
    buf[1] === 0xC2 &&
    buf[2] === 0x11 &&
    buf[3] === 0xD3 &&
    buf[196] === 0x5A
) {
    const samples = [];
    for (let offset = 0; offset + 197 <= buf.length; offset += 197) {
        if (
            buf[offset] !== 0xA5 ||
            buf[offset + 1] !== 0xC2 ||
            buf[offset + 2] !== 0x11 ||
            buf[offset + 3] !== 0xD3 ||
            buf[offset + 196] !== 0x5A
        ) {
            break;
        }
        for (let s = 0; s < 6; s++) {
            const row = [];
            for (let ch = 0; ch < 8; ch++) {
                const val = buf.readFloatLE(offset + 4 + (s * 8 + ch) * 4);
                row.push(Number.isFinite(val) ? Number(val.toFixed(3)) : 0);
            }
            samples.push(row);
        }
    }
    if (samples.length === 0) return null;

    const deviceCode = global.get("hwActiveDeviceCode") || defaultCode;
    const sampleRateSps = global.get("hwLastRateSps") || 500;
    msg.topic = "samples";
    msg.url = apiUrl + "/api/devices/ingest/samples";
    msg.headers = headers;
    msg.payload = {
        deviceCode,
        montage: "neurolink6",
        sampleRateSps,
        source: "NODERED",
        samples
    };
    return msg;
}

// 2) JSON telemetry heartbeat (String, UTF-8 Buffer, or pre-parsed Object)
let telemetry = null;
if (raw && typeof raw === "object" && !Buffer.isBuffer(raw)) {
    telemetry = raw;
} else {
    const text = buf ? buf.toString("utf8").trim() : (typeof raw === "string" ? raw.trim() : "");
    if (!text.startsWith("{")) return null;
    try {
        telemetry = JSON.parse(text);
    } catch (_err) {
        node.warn("Ignored malformed JSON frame on /ws/hardware");
        return null;
    }
}

const deviceCode = telemetry.deviceCode || telemetry.device_code || global.get("hwActiveDeviceCode") || defaultCode;
global.set("hwActiveDeviceCode", deviceCode);
if (Number.isFinite(Number(telemetry.rate_sps)) && Number(telemetry.rate_sps) > 0) {
    global.set("hwLastRateSps", Number(telemetry.rate_sps));
}

msg.topic = "telemetry";
msg.url = apiUrl + "/api/devices/ingest/telemetry";
msg.headers = headers;
msg.payload = {
    deviceCode,
    source: "NODERED",
    telemetry
};
return msg;

const body = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
const command = typeof body.command === "string" ? body.command.trim() : "";
const deviceCode = typeof body.deviceCode === "string" && body.deviceCode.trim()
    ? body.deviceCode.trim()
    : (global.get("defaultDeviceCode") || "NL-HOLTER-01");

if (!command || command.length > 128) {
    msg.statusCode = 400;
    msg.headers = { "Content-Type": "application/json" };
    msg.payload = { ok: false, forwarded: false, error: "Invalid or missing command" };
    return [null, msg];
}

// Output 1: clean text frame broadcast to connected ESP32 WebSocket clients (no _session lock)
const wsMsg = { payload: command };

// Output 2: HTTP JSON confirmation back to caller (Express backend or operator)
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    ok: true,
    forwarded: true,
    command,
    deviceCode
};
return [wsMsg, msg];

let startedAt = flow.get("startedAt");
if (!startedAt) {
    startedAt = Date.now();
    flow.set("startedAt", startedAt);
}
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    status: "online",
    runtime: "Node-RED",
    targetApi: (global.get("neurolinkApiUrl") || "http://127.0.0.1:4000").replace(/\/+$/, ""),
    wsPath: "/ws/hardware",
    defaultDeviceCode: global.get("defaultDeviceCode") || "NL-HOLTER-01",
    uptimeSec: Math.max(0, Math.round((Date.now() - startedAt) / 1000))
};
return msg;

const raw = msg.payload;
const buf = Buffer.isBuffer(raw) ? raw : null;

// Ignore 197-byte binary EEG waveform frames
if (buf && buf.length >= 197 && buf[0] === 0xA5 && buf[1] === 0xC2 && buf[2] === 0x11 && buf[3] === 0xD3) {
    return null;
}

let t = null;
if (raw && typeof raw === "object" && !Buffer.isBuffer(raw)) {
    t = raw;
} else {
    const text = buf ? buf.toString("utf8").trim() : (typeof raw === "string" ? raw.trim() : "");
    if (!text.startsWith("{")) return null;
    try {
        t = JSON.parse(text);
    } catch (_err) {
        return null;
    }
}

const apiUrl = (global.get("neurolinkApiUrl") || "http://127.0.0.1:4000").replace(/\/+$/, "");
const secret = global.get("ingestSecret") || "neurolink-nodered-dev-secret";
const deviceCode = t.deviceCode || t.device_code || global.get("hwActiveDeviceCode") || global.get("defaultDeviceCode") || "NL-HOLTER-01";
const now = Date.now();
const debounceMap = flow.get("alertDebounce") || {};
const DEBOUNCE_MS = 30000;

const candidates = [];

if (t.ai_state === "STROKE_ALERT") {
    const rf = Number(t.ai_rf_prob ?? 0).toFixed(2);
    const bsi = Number(t.ai_bsi ?? 0).toFixed(2);
    const dar = Number(t.ai_dar ?? 0).toFixed(2);
    candidates.push({
        severity: "CRITICAL",
        code: "STROKE_ALERT",
        message: "Edge AI phát hiện cảnh báo đột quỵ cấp (RF=" + rf + ", BSI=" + bsi + ", DAR=" + dar + ")."
    });
}

const vbatMv = Number(t.vbat_mv ?? 0);
if (Number.isFinite(vbatMv) && vbatMv > 0 && vbatMv < 3450) {
    const pct = Number(t.bat_pct ?? 0);
    candidates.push({
        severity: vbatMv < 3350 ? "CRITICAL" : "WARNING",
        code: "LOW_BATTERY",
        message: "Pin thiết bị Holter thấp (" + vbatMv + " mV / " + pct + "%). Vui lòng sạc pin sớm."
    });
}

const loffMask = Number(t.loff_p ?? 0);
if (Number.isFinite(loffMask) && loffMask > 0) {
    candidates.push({
        severity: "WARNING",
        code: "LEAD_OFF",
        message: "Phát hiện tuột điện cực (Lead-Off mask: 0x" + loffMask.toString(16).toUpperCase() + ")."
    });
}

const outgoing = [];
for (const alert of candidates) {
    const key = deviceCode + ":" + alert.code;
    const lastTs = debounceMap[key] || 0;
    if (now - lastTs < DEBOUNCE_MS) continue;
    debounceMap[key] = now;
    outgoing.push({
        topic: alert.severity,
        url: apiUrl + "/api/devices/ingest/alert",
        headers: {
            "x-nodered-secret": secret,
            "Content-Type": "application/json"
        },
        payload: {
            deviceCode,
            severity: alert.severity,
            code: alert.code,
            message: alert.message
        }
    });
}

flow.set("alertDebounce", debounceMap);
if (outgoing.length === 0) return null;
return [outgoing];

const apiUrl = (global.get("neurolinkApiUrl") || "http://127.0.0.1:4000").replace(/\/+$/, "");
const deviceCode = global.get("hwActiveDeviceCode") || global.get("defaultDeviceCode") || "NL-HOLTER-01";
const sampleRateSps = global.get("hwLastRateSps") || 500;
const channelNames = ["F3", "F4", "C3", "C4", "O1", "O2", "T3", "T4"];
const targetSamples = Math.max(250, Math.round(sampleRateSps * 4)); // 4-second epoch

let buffer = flow.get("epochBuffer") || [];

if (msg.topic !== "flush") {
    const raw = msg.payload;
    if (!Buffer.isBuffer(raw) || raw.length < 197) return null;
    if (raw[0] !== 0xA5 || raw[1] !== 0xC2 || raw[2] !== 0x11 || raw[3] !== 0xD3 || raw[196] !== 0x5A) {
        return null;
    }
    for (let offset = 0; offset + 197 <= raw.length; offset += 197) {
        if (
            raw[offset] !== 0xA5 ||
            raw[offset + 1] !== 0xC2 ||
            raw[offset + 2] !== 0x11 ||
            raw[offset + 3] !== 0xD3 ||
            raw[offset + 196] !== 0x5A
        ) {
            break;
        }
        for (let s = 0; s < 6; s++) {
            const row = [];
            for (let ch = 0; ch < 8; ch++) {
                const val = raw.readFloatLE(offset + 4 + (s * 8 + ch) * 4);
                row.push(Number.isFinite(val) ? Number(val.toFixed(3)) : 0);
            }
            buffer.push(row);
        }
    }
}

const ready = (msg.topic === "flush" && buffer.length >= 64) || buffer.length >= targetSamples;
if (!ready) {
    if (buffer.length > targetSamples * 2) {
        buffer = buffer.slice(-targetSamples);
    }
    flow.set("epochBuffer", buffer);
    return null;
}

const epoch = buffer.slice(0, targetSamples);
flow.set("epochBuffer", buffer.slice(epoch.length));

const headerLine = channelNames.join(",");
const csvLines = [headerLine];
for (let i = 0; i < epoch.length; i++) {
    csvLines.push(epoch[i].join(","));
}
const csvFull = csvLines.join("\n");
const csvSummary = csvLines.slice(0, Math.min(csvLines.length, 61)).join("\n");
const durationSec = Number((epoch.length / sampleRateSps).toFixed(2));

msg.url = apiUrl + "/api/qeeg/analyze-csv";
msg.headers = { "Content-Type": "application/json" };
msg._epochMeta = {
    deviceCode,
    montage: "neurolink6",
    sampleRateSps,
    channelNames,
    sampleCount: epoch.length,
    durationSec,
    csvSummary
};
msg.payload = {
    filename: deviceCode + "_epoch_" + Date.now() + ".csv",
    csvText: csvFull,
    samplingRateHz: sampleRateSps,
    clinicalCategory: "HARDWARE_BCI"
};
return msg;

const apiUrl = (global.get("neurolinkApiUrl") || "http://127.0.0.1:4000").replace(/\/+$/, "");
const secret = global.get("ingestSecret") || "neurolink-nodered-dev-secret";
const meta = msg._epochMeta || {
    deviceCode: global.get("defaultDeviceCode") || "NL-HOLTER-01",
    montage: "neurolink6",
    sampleRateSps: 500,
    channelNames: ["F3", "F4", "C3", "C4", "O1", "O2", "T3", "T4"],
    sampleCount: 0,
    durationSec: 4,
    csvSummary: ""
};

msg.url = apiUrl + "/api/devices/ingest/epoch";
msg.headers = {
    "x-nodered-secret": secret,
    "Content-Type": "application/json"
};
msg.payload = {
    deviceCode: meta.deviceCode,
    title: "Node-RED 4s qEEG Epoch (" + meta.deviceCode + ")",
    montage: meta.montage,
    sampleRateSps: meta.sampleRateSps,
    channelNames: meta.channelNames,
    sampleCount: Math.max(1, Number(meta.sampleCount) || 1),
    durationSec: Math.max(0.01, Number(meta.durationSec) || 4),
    csvSummary: meta.csvSummary,
    qeegResultJson: msg.payload
};
return msg;

const scenario = String(msg.payload || "normal");
const apiUrl = (global.get("neurolinkApiUrl") || "http://127.0.0.1:4000").replace(/\/+$/, "");
const secret = global.get("ingestSecret") || "neurolink-nodered-dev-secret";
const deviceCode = global.get("defaultDeviceCode") || "NL-HOLTER-01";
const headers = {
    "x-nodered-secret": secret,
    "Content-Type": "application/json"
};

const sampleRateSps = 500;
const nSamples = 250; // 0.5s realistic burst @ 500 Hz
const samples = [];

for (let i = 0; i < nSamples; i++) {
    const t = i / sampleRateSps;
    const row = [];
    for (let ch = 0; ch < 8; ch++) {
        const isLeft = ch % 2 === 0;
        const isOccipital = ch === 4 || ch === 5;
        let val = 0;
        if (scenario === "stroke_alert" && isLeft) {
            val = 52 * Math.sin(2 * Math.PI * 2.2 * t + ch * 0.3)
                + 11 * Math.sin(2 * Math.PI * 4.5 * t)
                + (Math.random() - 0.5) * 4;
        } else {
            const alphaAmp = isOccipital ? 20 : 11;
            val = alphaAmp * Math.sin(2 * Math.PI * 10.0 * t + ch * 0.25)
                + 5.5 * Math.sin(2 * Math.PI * 6.0 * t + ch * 0.5)
                + 2.5 * Math.sin(2 * Math.PI * 20.0 * t)
                + (Math.random() - 0.5) * 2.5;
        }
        row.push(Number(val.toFixed(3)));
    }
    samples.push(row);
}

let telemetry = {
    type: "telemetry",
    fw: "V3.0.0",
    mode: "EEG",
    rate_sps: sampleRateSps,
    pga: 24,
    sps: 499.8,
    sd_rec: true,
    markers: 1,
    usb_only: false,
    vbat_mv: 3920,
    bat_pct: 84,
    loff_p: 0,
    ai_state: "NORMAL",
    ai_rf_prob: 0.09,
    ai_lr_prob: 0.07,
    ai_bsi: 0.15,
    ai_dar: 1.38,
    ai_usable_ch: 8
};

let alertMsg = null;

if (scenario === "stroke_alert") {
    telemetry = {
        ...telemetry,
        vbat_mv: 3810,
        bat_pct: 72,
        ai_state: "STROKE_ALERT",
        ai_rf_prob: 0.91,
        ai_lr_prob: 0.87,
        ai_bsi: 0.68,
        ai_dar: 5.42
    };
    alertMsg = {
        url: apiUrl + "/api/devices/ingest/alert",
        headers,
        payload: {
            deviceCode,
            severity: "CRITICAL",
            code: "STROKE_ALERT",
            message: "[Node-RED Sim] Cảnh báo đột quỵ cấp: bất đối xứng Delta bán cầu trái (RF=0.91, BSI=0.68, DAR=5.42)."
        }
    };
} else if (scenario === "low_battery") {
    telemetry = {
        ...telemetry,
        vbat_mv: 3380,
        bat_pct: 12,
        sd_rec: false
    };
    alertMsg = {
        url: apiUrl + "/api/devices/ingest/alert",
        headers,
        payload: {
            deviceCode,
            severity: "WARNING",
            code: "LOW_BATTERY",
            message: "[Node-RED Sim] Pin Holter giảm xuống 3.38V (12%). Khuyến nghị sạc pin ngay."
        }
    };
}

const telemetryMsg = {
    url: apiUrl + "/api/devices/ingest/telemetry",
    headers,
    payload: {
        deviceCode,
        source: "NODERED",
        telemetry
    }
};

const samplesMsg = {
    url: apiUrl + "/api/devices/ingest/samples",
    headers,
    payload: {
        deviceCode,
        montage: "neurolink6",
        sampleRateSps,
        source: "NODERED",
        samples
    }
};

return [telemetryMsg, samplesMsg, alertMsg];
